# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student("id", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_splits(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Zane", "Olga")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Olga"
            ]
        )

    def test_bad_seats(self):
        people = [make("Zane", "Olga")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
